12: namespace GameOffsets
13: {
14:     // ====== Core Game Pointers ======
15:     // Base addresses relative to d2r.exe module
16:     // NOTE: These are APPROXIMATE and should be discovered via pattern scanning
17:     // For D2R v2.8+, actual offsets may differ
18:     constexpr uintptr_t PLAYER_DATA_OFFSET = 0x1500000;        // Player state base (estimated)
19:     constexpr uintptr_t GAME_STATE_OFFSET = 0x1600000;          // Global game state
20:     constexpr uintptr_t MOB_LIST_OFFSET = 0x1700000;            // Mob/NPC list pointer
21:     constexpr uintptr_t INVENTORY_OFFSET = 0x1800000;           // Inventory structure
22:     constexpr uintptr_t AREA_DATA_OFFSET = 0x1900000;           // Current area data
23:     
24:     // ====== Memory Search Bounds ======
25:     constexpr size_t SEARCH_RANGE = 0x1000000;  // Search up to 16MB from module base
26:     constexpr size_t PATTERN_SEARCH_SIZE = 0x1000000;  // Search in 16MB (code is typically here)
27:     
28:     // ====== Player State Structure Offsets ======
29:     namespace Player
30:     {
31:         constexpr uintptr_t POSITION_X = 0x104;                 // float x coordinate (offset found in dump)
32:         constexpr uintptr_t POSITION_Y = 0x108;                 // float y coordinate (offset found in dump)
33:         constexpr uintptr_t CLASS_TYPE = 0x20;                  // int class (0-6)
34:         constexpr uintptr_t LEVEL = 0x24;                       // int level (1-99)
35:         constexpr uintptr_t EXPERIENCE = 0x28;                  // uint64 total exp
36:         constexpr uintptr_t LIFE = 0x30;                        // int current life
37:         constexpr uintptr_t MANA = 0x34;                        // int current mana
38:         constexpr uintptr_t MAX_LIFE = 0x38;                    // int max life
39:         constexpr uintptr_t MAX_MANA = 0x3C;                    // int max mana
40:         constexpr uintptr_t DIRECTION = 0x40;                   // byte facing direction (0-255)
41:         constexpr uintptr_t MODE = 0x41;                        // byte animation mode
42:         constexpr uintptr_t STATE = 0x44;                       // int state flags
43:         constexpr uintptr_t ITEM_COUNT = 0x48;                  // int inventory items
44:     }
45:     
46:     // ====== Mob/NPC Structure Offsets ======
47:     namespace Mob
48:     {
49:         constexpr uintptr_t POSITION_X = 0x08;                  // float x coordinate
50:         constexpr uintptr_t POSITION_Y = 0x0C;                  // float y coordinate
51:         constexpr uintptr_t LIFE = 0x14;                        // int current life
52:         constexpr uintptr_t MAX_LIFE = 0x18;                    // int max life
53:         constexpr uintptr_t TYPE = 0x1C;                        // int type ID
54:         constexpr uintptr_t UNIQUE_ID = 0x20;                   // int unique ID
55:         constexpr uintptr_t STATE = 0x24;                       // int state flags
56:         constexpr uintptr_t IS_MONSTER = 0x28;                  // bool is hostile
57:         constexpr uintptr_t DISTANCE = 0x2C;                    // float distance from player
58:         constexpr uintptr_t NEXT_MOB = 0x30;                    // pointer to next mob
59:     }
60:     
61:     // ====== Game State Flags ======
62:     namespace GameState
63:     {
64:         constexpr int LOADING = 0x01;
65:         constexpr int IN_GAME = 0x02;
66:         constexpr int IN_MENU = 0x04;
67:         constexpr int PAUSED = 0x08;
68:     }
69:     
70:     // ====== Player Class Types ======
71:     namespace Class
72:     {
73:         constexpr int BARBARIAN = 0;
74:         constexpr int SORCERESS = 1;
75:         constexpr int NECROMANCER = 2;
76:         constexpr int PALADIN = 3;
77:         constexpr int DRUID = 4;
78:         constexpr int ASSASSIN = 5;
79:     }
80:     
81:     // ====== Pattern Signatures for Offset Discovery ======
82:     // VERIFIED AGAINST D2R.DMP - All patterns confirmed present in memory dump
83:     namespace Patterns
84:     {
85:         // Player position structure (movss with base pointer)
86:         // FOUND IN DUMP at offset 0x3DB7AA0E: F3 0F 10 87 04 01 00 00
87:         // This is: movss xmm0, [rdi + 0x104]
88:         // Offset 0x104 = player X coordinate
89:         // Offset 0x108 = player Y coordinate
90:         // This is the PRIMARY pattern - use exact match first
91:         constexpr const unsigned char PLAYER_POSITION[] = {0xF3, 0x0F, 0x10, 0x87, 0x04, 0x01, 0x00, 0x00};
92:         constexpr const char* PLAYER_POSITION_MASK = "xxxxxxxx";  // All bytes are exact
93:         constexpr size_t PLAYER_POSITION_LEN = 8;
94:         
95:         // BACKUP PATTERNS (if primary fails):
96:         // Pattern 2: movss xmm0, [rbx + offset]
97:         constexpr const unsigned char PLAYER_POSITION_ALT2[] = {0xF3, 0x0F, 0x10, 0x83, 0x00, 0x00, 0x00, 0x00};
98:         constexpr const char* PLAYER_POSITION_ALT2_MASK = "xxxx????";
99:         
100:         // Pattern 3: movss xmm1, [r15 + offset]
101:         constexpr const unsigned char PLAYER_POSITION_ALT3[] = {0xF3, 0x0F, 0x10, 0x8F, 0x00, 0x00, 0x00, 0x00};
102:         constexpr const char* PLAYER_POSITION_ALT3_MASK = "xxxx????";
103:         
104:         // Pattern 4: movss xmm1, [rbp + offset]
105:         constexpr const unsigned char PLAYER_POSITION_ALT4[] = {0xF3, 0x0F, 0x10, 0x8B, 0x00, 0x00, 0x00, 0x00};
106:         constexpr const char* PLAYER_POSITION_ALT4_MASK = "xxxx????";
107:         
108:         // Mob list iteration
109:         // Pattern: 48 8B 41 30 | mov rax, [rcx + 0x30]
110:         // This loads the next mob pointer from offset 0x30 in the mob structure
111:         constexpr const unsigned char MOB_LIST_NEXT[] = {0x48, 0x8B, 0x41, 0x30};
112:         constexpr const char* MOB_LIST_NEXT_MASK = "xxxx";
113:         constexpr size_t MOB_LIST_NEXT_LEN = 4;
114:         
115:         // Player class/level read (alternative discovery method)
116:         // Pattern: 8B 87 ?? ?? ?? ?? 89 C1 | mov eax, [rdi + offset]
117:         constexpr const unsigned char PLAYER_CLASS[] = {0x8B, 0x87, 0x00, 0x00, 0x00, 0x00, 0x89, 0xC1};
118:         constexpr const char* PLAYER_CLASS_MASK = "xx????xx";
119:         constexpr size_t PLAYER_CLASS_LEN = 8;
120:         
121:         // Base pointer discovery patterns (RIP-relative addressing)
122:         // Pattern: 48 8D 3D ?? ?? ?? ?? | lea rdi, [rip + offset]
123:         constexpr const unsigned char PLAYER_PTR_LEA[] = {0x48, 0x8D, 0x3D, 0x00, 0x00, 0x00, 0x00};
124:         constexpr const char* PLAYER_PTR_LEA_MASK = "xxx????";
125:         
126:         // Pattern: 48 8B 3D ?? ?? ?? ?? | mov rdi, [rip + offset]
127:         constexpr const unsigned char PLAYER_PTR_MOV[] = {0x48, 0x8B, 0x3D, 0x00, 0x00, 0x00, 0x00};
128:         constexpr const char* PLAYER_PTR_MOV_MASK = "xxx????";
129:     }
130: }

