27:         if (pKeyBoard->vkCode == VK_OEM_3 && wParam == WM_KEYDOWN)
28:         {
29:             // Check if D2R window is in focus
30:             HWND foreground = GetForegroundWindow();
31:             HWND gameWindow = FindWindowA(nullptr, "Diablo II: Resurrected");
32:             if (!gameWindow)
33:                 gameWindow = FindWindowA(nullptr, "D2R");
34: 
35:             // Only toggle if D2R is active
36:             if (foreground == gameWindow && BotEngine::s_instance)
37:             {
38:                 // Toggle running state
39:                 if (BotEngine::s_instance->m_isRunning)
40:                 {
41:                     BotEngine::s_instance->Stop();
42:                 }
43:                 else
44:                 {
45:                     // Start with current route
46:                     BotEngine::s_instance->Start(BotEngine::s_instance->m_currentRoute.c_str());
47:                 }
48:             }
49:         }
50:     }
51: 
52:     return CallNextHookEx(BotEngine::s_keyboardHook, nCode, wParam, lParam);
