95: bool BotEngine::FindGameProcess()
96: {
97:     PROCESSENTRY32 pe32;
98:     pe32.dwSize = sizeof(PROCESSENTRY32);
99: 
100:     HANDLE hProcessSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
101:     if (hProcessSnap == INVALID_HANDLE_VALUE)
102:         return false;
103: 
104:     // Look for Diablo II: Resurrected
105:     if (Process32First(hProcessSnap, &pe32))
106:     {
107:         do
108:         {
109:             if (_wcsicmp(pe32.szExeFile, L"D2R") == 0 || _wcsicmp(pe32.szExeFile, L"D2R.exe") == 0)
110:             {
111:                 m_processId = pe32.th32ProcessID;
112:                 CloseHandle(hProcessSnap);
113:                 return true;
114:             }
115:         } while (Process32Next(hProcessSnap, &pe32));
116:     }
117: 
118:     CloseHandle(hProcessSnap);
119:     return false;
120: }
