147: Vector2D BotEngine::GameCoordToScreenCoord(const Vector2D &gameCoord) const
148: {
149:     // D2R uses isometric projection
150:     // Screen X = (GameX - GameY) * cos(30°) + ScreenCenterX
151:     // Screen Y = (GameX + GameY) * sin(30°) + ScreenCenterY
152:     // For simplicity, approximate as 1:1 mapping with offset
153:     Vector2D screenCoord;
154:     screenCoord.x = gameCoord.x * 0.5f + gameCoord.y * 0.5f + 640.0f;
155:     screenCoord.y = gameCoord.x * 0.25f - gameCoord.y * 0.25f + 360.0f;
156:     return screenCoord;
157: }
