159: Vector2D BotEngine::ScreenCoordToGameCoord(const Vector2D &screenCoord) const
160: {
161:     // Inverse of above transformation
162:     Vector2D gameCoord;
163:     float sx = screenCoord.x - 640.0f;
164:     float sy = screenCoord.y - 360.0f;
165:     gameCoord.x = sx + sy * 2.0f;
166:     gameCoord.y = sx - sy * 2.0f;
167:     return gameCoord;
168: }
