    {
        if (!g_botEngine)
            return 0;
        return g_botEngine->GetStatus();
    }

    void __cdecl GetGameState(void **playerPos, void **nearbyMobs)
    {
        if (!g_botEngine || !g_botEngine->IsInitialized())
        {
            *playerPos = nullptr;
            *nearbyMobs = nullptr;
            return;
        }

        static PlayerState playerState;
        playerState = g_botEngine->GetPlayerState();

        if (playerState.position.x != 0 || playerState.position.y != 0)
        {
            *playerPos = &playerState;
        }
        else
        {
            *playerPos = nullptr;
        }

        *nearbyMobs = nullptr;
    }

    const char *__cdecl RunMemoryHookTests()
