        if (!g_botEngine || !g_botEngine->IsInitialized())
            return "Bot not initialized";

        static char resultBuffer[2048];

        try
        {
            PlayerState player = g_botEngine->GetPlayerState();
            std::vector<MobInfo> mobs = g_botEngine->GetNearbyMobs(200.0f);

            std::stringstream ss;
            ss << "=== D2R MEMORY HOOKS TEST ===\n";
            ss << "Using BMBot Unit Table Scanning\n\n";

            // Check if we're getting real data
            bool hasRealData = (player.position.x != 100.0f || player.position.y != 200.0f);

            if (!hasRealData)
            {
                ss << "[WARNING] Using fallback mock data\n";
                ss << "This means unit table discovery failed.\n";
                ss << "Possible causes:\n";
                ss << "  - D2R.exe not running\n";
                ss << "  - Pattern signature changed (D2R patched)\n";
                ss << "  - Access denied (run as Administrator)\n\n";
            }
            else
            {
                ss << "[SUCCESS] Real data from game memory\n\n";
            }

            ss << "Player Data:\n";
            ss << "  Position: (" << std::fixed << std::setprecision(2)
               << player.position.x << ", " << player.position.y << ")\n";
            ss << "  Class: " << player.classType << "\n";
            ss << "  Level: " << player.level << "\n";
            ss << "  Experience: " << player.experience << "\n\n";

            ss << "Mobs Detected: " << mobs.size() << " within 200 units\n";
            for (size_t i = 0; i < mobs.size() && i < 10; i++)
            {
                ss << "  [" << i << "] (" << std::fixed << std::setprecision(2)
                   << mobs[i].position.x << ", " << mobs[i].position.y << ") "
                   << "ID: " << mobs[i].uniqueId << " Alive: " << (mobs[i].isAlive ? "Yes" : "No") << "\n";
            }

            std::string result = ss.str();
            if (result.length() < sizeof(resultBuffer))
            {
                strcpy_s(resultBuffer, sizeof(resultBuffer), result.c_str());
            }
            else
            {
                strcpy_s(resultBuffer, sizeof(resultBuffer), "Result too large for buffer");
            }
        }
        catch (const std::exception &e)
        {
            snprintf(resultBuffer, sizeof(resultBuffer), "Exception: %s", e.what());
        }
        catch (...)
        {
            strcpy_s(resultBuffer, sizeof(resultBuffer), "Unknown exception");
        }

        return resultBuffer;
    }
}

