#include "BotEngine.h"
#include "GameOffsets.h"
#include "MemoryReader.h"
#include <tlhelp32.h>
#include <cstring>
#include <windows.h>
#include <chrono>
#include <cmath>
#include <cfloat>
#include <sstream>
#include <iomanip>

static BotEngine *g_botEngine = nullptr;

// Static members
HHOOK BotEngine::s_keyboardHook = nullptr;
BotEngine *BotEngine::s_instance = nullptr;

// Cache for unit table base address - discovered once, reused many times
static uintptr_t g_unitTableBase = 0;
static std::chrono::high_resolution_clock::time_point g_lastUnitTableDiscovery;

// Unit type constants (from BMBot)
enum UnitType
{
    UNIT_TYPE_PLAYER = 0,
    UNIT_TYPE_ITEM = 1,
    UNIT_TYPE_OBJECT = 2,
    UNIT_TYPE_MONSTER = 3
};

// Unit structure offsets (based on BMBot analysis)
namespace UnitOffsets
{
    constexpr uintptr_t TYPE = 0x00;              // byte - unit type
    constexpr uintptr_t UNIQUE_ID = 0x04;         // uint32 - unique ID
    constexpr uintptr_t POSITION_X = 0x08;        // float - X coordinate
    constexpr uintptr_t POSITION_Y = 0x0C;        // float - Y coordinate
    constexpr uintptr_t LIFE = 0x14;              // int - current HP
    constexpr uintptr_t MAX_LIFE = 0x18;          // int - max HP
    constexpr uintptr_t LEVEL = 0x20;             // byte - character level
    constexpr uintptr_t EXPERIENCE = 0x24;        // uint64 - total experience
    constexpr uintptr_t CLASS_TYPE = 0x28;        // int - class (player only)
    constexpr uintptr_t NEXT_UNIT = 0x30;         // ptr - next unit in list
    constexpr uintptr_t PLAYER_STATS = 0x40;      // Stats data begins around here
}

// Keyboard hook callback
LRESULT CALLBACK KeyboardHookProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode >= 0)
    {
        KBDLLHOOKSTRUCT *pKeyBoard = (KBDLLHOOKSTRUCT *)lParam;

        // Only respond to backtick/tilde key (VK_OEM_3)
        if (pKeyBoard->vkCode == VK_OEM_3 && wParam == WM_KEYDOWN)
        {
            // Check if D2R window is in focus
            HWND foreground = GetForegroundWindow();
            HWND gameWindow = FindWindowA(nullptr, "Diablo II: Resurrected");
            if (!gameWindow)
                gameWindow = FindWindowA(nullptr, "D2R");

            // Only toggle if D2R is active
            if (foreground == gameWindow && BotEngine::s_instance)
            {
                // Toggle running state
                if (BotEngine::s_instance->m_isRunning)
                {
                    BotEngine::s_instance->Stop();
                }
                else
                {
                    // Start with current route
                    BotEngine::s_instance->Start(BotEngine::s_instance->m_currentRoute.c_str());
                }
            }
        }
    }

    return CallNextHookEx(BotEngine::s_keyboardHook, nCode, wParam, lParam);
}

BotEngine::BotEngine()
    : m_processHandle(nullptr), m_processId(0), m_isRunning(false), m_isInitialized(false)
{
}

BotEngine::~BotEngine()
{
    Stop();
    if (m_processHandle)
    {
        CloseHandle(m_processHandle);
    }
}

bool BotEngine::Initialize()
{
    if (m_isInitialized)
        return true;

    if (!FindGameProcess())
    {
        return false;
    }

    if (!AttachToProcess(m_processId))
    {
        return false;
    }

    // Set up keyboard hook for backtick toggle
    s_instance = this;
    if (!s_keyboardHook)
    {
        s_keyboardHook = SetWindowsHookEx(WH_KEYBOARD_LL, KeyboardHookProc, GetModuleHandleA(nullptr), 0);
    }

    m_isInitialized = true;
    return true;
}

bool BotEngine::FindGameProcess()
{
    PROCESSENTRY32 pe32;
    pe32.dwSize = sizeof(PROCESSENTRY32);

    HANDLE hProcessSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (hProcessSnap == INVALID_HANDLE_VALUE)
        return false;

    // Look for Diablo II: Resurrected
    if (Process32First(hProcessSnap, &pe32))
    {
        do
        {
            if (_wcsicmp(pe32.szExeFile, L"D2R") == 0 || _wcsicmp(pe32.szExeFile, L"D2R.exe") == 0)
            {
                m_processId = pe32.th32ProcessID;
                CloseHandle(hProcessSnap);
                return true;
            }
        } while (Process32Next(hProcessSnap, &pe32));
    }

    CloseHandle(hProcessSnap);
    return false;
}

bool BotEngine::AttachToProcess(DWORD processId)
{
    m_processHandle = OpenProcess(
        PROCESS_ALL_ACCESS,
        FALSE,
        processId);

    return m_processHandle != nullptr;
}

bool BotEngine::Stop()
{
    m_isRunning = false;
    return true;
}

int BotEngine::GetStatus() const
{
    return m_isRunning ? 1 : 0;
}

/**
 * Discovers the unit table base address by pattern scanning
 * This is the root pointer from which all game units (player, mobs, items) can be accessed
 * Pattern: "48 03 C7 49 8B 8C C6" - Used in BMBot
 */
uintptr_t BotEngine::DiscoverUnitTableBase(const MemoryReader& reader, uintptr_t d2rModuleBase) const
{
    // Check cache first (refresh every 30 seconds)
    auto now = std::chrono::high_resolution_clock::now();
    if (g_unitTableBase != 0)
    {
        auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(now - g_lastUnitTableDiscovery);
        if (elapsed.count() < 30)
        {
            return g_unitTableBase;
        }
    }

    try
    {
        // Primary pattern: "48 03 C7 49 8B 8C C6"
        // This is: add rax, rdi; mov rcx, [rsi + rcx*8 + offset]
        // Found in BMBot PatternsScan.cs line 159
        const unsigned char unitTablePattern[] = {0x48, 0x03, 0xC7, 0x49, 0x8B, 0x8C, 0xC6};
        const char* unitTableMask = "xxxxxxx";

        uintptr_t found = reader.FindPatternEx(
            unitTablePattern,
            unitTableMask,
            d2rModuleBase,
            GameOffsets::PATTERN_SEARCH_SIZE);

        if (found != 0)
        {
            // Read the offset at found+7 (4 bytes, RIP-relative)
            int32_t rip_offset = reader.Read<int32_t>(found + 7);
            // Calculate: address of next instruction (found + 11) + signed offset
            uintptr_t unitTablePtr = found + 11 + rip_offset;

            g_unitTableBase = unitTablePtr;
            g_lastUnitTableDiscovery = now;
            return unitTablePtr;
        }
    }
    catch (...)
    {
        // Fall through
    }

    return 0;
}

/**
 * Scans the unit table for a unit of specific type
 * Mimics BMBot's unit scanning with 0x48 and 0x170 byte stride alternation
 */
uintptr_t BotEngine::FindUnitByType(const MemoryReader& reader, UnitType targetType, 
                                    int maxScans = 2600) const
{
    if (!m_processHandle)
        return 0;

    try
    {
        // Get D2R module base
        MODULEENTRY32 me32 = {sizeof(MODULEENTRY32)};
        HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, m_processId);
        if (hModuleSnap == INVALID_HANDLE_VALUE)
            return 0;

        uintptr_t moduleBase = 0;
        if (Module32First(hModuleSnap, &me32))
        {
            do
            {
                if (_wcsicmp(me32.szModule, L"D2R.exe") == 0)
                {
                    moduleBase = (uintptr_t)me32.modBaseAddr;
                    break;
                }
            } while (Module32Next(hModuleSnap, &me32));
        }
        CloseHandle(hModuleSnap);

        if (!moduleBase)
            return 0;

        // Discover unit table
        uintptr_t unitTablePtr = DiscoverUnitTableBase(reader, moduleBase);
        if (!unitTablePtr)
            return 0;

        // Read unit table pointer
        uintptr_t unitTableBase = reader.Read<uintptr_t>(unitTablePtr);
        if (!unitTableBase)
            return 0;

        // Scan with alternating stride (like BMBot)
        // 0x48 and 0x170 byte sizes for different unit types
        uintptr_t currentOffset = unitTableBase;

        for (int i = 0; i < maxScans; i++)
        {
            // Alternate stride: 0x48 on odd, 0x170 on even
            if ((i % 2) == 1)
                currentOffset += 0x48;
            else
                currentOffset += 0x170;

            // Check unit type at offset 0x00
            byte unitType = reader.Read<byte>(currentOffset + UnitOffsets::TYPE);

            if (unitType == targetType)
            {
                // Found the unit type we're looking for
                return currentOffset;
            }

            // Safety check for bad pointer
            if (currentOffset == 0 || currentOffset > 0x00007FFFFFFF000000ULL)
                break;
        }
    }
    catch (...)
    {
        // Fall through to fallback
    }

    return 0;
}

bool BotEngine::Start(const char *route)
{
    if (!m_isInitialized)
        return false;

    m_isRunning = true;
    m_currentRoute = route;

    // Start route execution in a separate thread
    std::thread routeThread(&BotEngine::ExecuteRoute, this, route);
    routeThread.detach(); // Let thread run independently

    return true;
}

Vector2D BotEngine::GameCoordToScreenCoord(const Vector2D &gameCoord) const
{
    // D2R uses isometric projection
    Vector2D screenCoord;
    screenCoord.x = gameCoord.x * 0.5f + gameCoord.y * 0.5f + 640.0f;
    screenCoord.y = gameCoord.x * 0.25f - gameCoord.y * 0.25f + 360.0f;
    return screenCoord;
}

Vector2D BotEngine::ScreenCoordToGameCoord(const Vector2D &screenCoord) const
{
    // Inverse transformation
    Vector2D gameCoord;
    float sx = screenCoord.x - 640.0f;
    float sy = screenCoord.y - 360.0f;
    gameCoord.x = sx + sy * 2.0f;
    gameCoord.y = sx - sy * 2.0f;
    return gameCoord;
}

void BotEngine::ExecuteRoute(const char *route)
{
    // Find D2R window to send input to
    HWND hGameWindow = FindWindowA(nullptr, "Diablo II: Resurrected");
    if (!hGameWindow)
        hGameWindow = FindWindowA(nullptr, "D2R");
    if (!hGameWindow)
        hGameWindow = GetForegroundWindow();

    if (!hGameWindow || !m_processHandle)
        return;

    SetForegroundWindow(hGameWindow);
    Sleep(200);

    // Route waypoint coordinates (screen positions for clicking)
    struct Waypoint
    {
        int x;
        int y;
        const char *name;
    };

    // Cow Level - comprehensive area coverage
    Waypoint cowLevelRoute[] = {
        {450, 280, "NW1"}, {520, 260, "N"}, {620, 270, "NE1"}, {750, 280, "NE2"},
        {850, 320, "E1"}, {900, 380, "E2"}, {860, 450, "SE1"}, {750, 500, "SE2"},
        {600, 520, "S1"}, {450, 500, "S2"}, {300, 450, "SW1"}, {250, 380, "SW2"},
        {300, 280, "W1"}, {380, 260, "W2"}, {450, 280, "NW2"}, {600, 380, "Center"},
    };

    // Pit route
    Waypoint pitRoute[] = {
        {600, 320, "Entrance"}, {630, 300, "Upper"}, {670, 310, "UpperRight"},
        {700, 340, "RightChamber"}, {720, 380, "LowerRight"}, {680, 420, "Bottom"},
        {630, 410, "LowerMiddle"}, {580, 390, "LeftChamber"}, {550, 340, "Left"},
        {560, 280, "UpperLeft"}, {600, 350, "Center"},
    };

    // Ancient Tunnels route
    Waypoint ancientTunnelsRoute[] = {
        {600, 300, "NorthTunnel"}, {650, 280, "NorthEastBranch"}, {700, 310, "EastCorridor"},
        {730, 360, "EastEnd"}, {720, 410, "SouthEastBranch"}, {650, 440, "SouthTunnel"},
        {580, 430, "SouthWestBranch"}, {530, 380, "WestCorridor"}, {500, 320, "WestEnd"},
        {520, 270, "NorthWestBranch"}, {600, 350, "Center"},
    };

    // Select route
    Waypoint *selectedRoute = nullptr;
    int routeLength = 0;

    if (strcmp(route, "cow") == 0)
    {
        selectedRoute = cowLevelRoute;
        routeLength = sizeof(cowLevelRoute) / sizeof(cowLevelRoute[0]);
    }
    else if (strcmp(route, "pit") == 0)
    {
        selectedRoute = pitRoute;
        routeLength = sizeof(pitRoute) / sizeof(pitRoute[0]);
    }
    else if (strcmp(route, "ancient") == 0)
    {
        selectedRoute = ancientTunnelsRoute;
        routeLength = sizeof(ancientTunnelsRoute) / sizeof(ancientTunnelsRoute[0]);
    }
    else
    {
        return; // Unknown route
    }

    // Execute route
    int waypointIndex = 0;
    while (m_isRunning && selectedRoute && waypointIndex < routeLength)
    {
        Waypoint& wp = selectedRoute[waypointIndex];

        // Send click to waypoint
        INPUT input[2] = {};

        // Move mouse
        input[0].type = INPUT_MOUSE;
        input[0].mi.dx = wp.x * 65536 / 1920;  // Normalize to screen coords
        input[0].mi.dy = wp.y * 65536 / 1080;
        input[0].mi.dwFlags = MOUSEEVENTF_MOVE | MOUSEEVENTF_ABSOLUTE;

        // Click
        input[1].type = INPUT_MOUSE;
        input[1].mi.dwFlags = MOUSEEVENTF_LEFTDOWN;

        SendInput(2, input, sizeof(INPUT));
        Sleep(100);

        // Release click
        INPUT releaseInput = {};
        releaseInput.type = INPUT_MOUSE;
        releaseInput.mi.dwFlags = MOUSEEVENTF_LEFTUP;
        SendInput(1, &releaseInput, sizeof(INPUT));

        Sleep(500); // Wait for character to move
        waypointIndex++;
    }
}

/**
 * Gets the player state by reading from game memory
 * Uses unit table scanning to find the player unit
 */
PlayerState BotEngine::GetPlayerState() const
{
    PlayerState state = {};

    if (!m_processHandle || !m_isInitialized)
        return state;

    try
    {
        MemoryReader reader(m_processHandle);

        // Find the player unit (type 0)
        uintptr_t playerUnit = FindUnitByType(reader, UNIT_TYPE_PLAYER);

        if (playerUnit != 0)
        {
            // Read player data from unit structure
            state.position.x = reader.Read<float>(playerUnit + UnitOffsets::POSITION_X);
            state.position.y = reader.Read<float>(playerUnit + UnitOffsets::POSITION_Y);
            state.classType = reader.Read<int>(playerUnit + UnitOffsets::CLASS_TYPE);
            state.level = reader.Read<int>(playerUnit + UnitOffsets::LEVEL);
            state.experience = reader.Read<int>(playerUnit + UnitOffsets::EXPERIENCE);

            // Validate data (sanity check)
            if (state.position.x >= -10000.0f && state.position.x <= 10000.0f &&
                state.position.y >= -10000.0f && state.position.y <= 10000.0f &&
                state.level >= 1 && state.level <= 99 &&
                state.classType >= 0 && state.classType <= 5)
            {
                return state; // Valid player data
            }
        }
    }
    catch (...)
    {
        // Fall through to fallback
    }

    // Fallback: return mock data
    state.position.x = 100.0f;
    state.position.y = 200.0f;
    state.classType = 0;
    state.level = 1;
    state.experience = 0;
    return state;
}

/**
 * Gets nearby mobs by scanning the unit table
 * Uses the same unit table scanning as GetPlayerState
 */
std::vector<MobInfo> BotEngine::GetNearbyMobs(float radius) const
{
    std::vector<MobInfo> mobs;

    if (!m_processHandle || !m_isInitialized)
        return mobs;

    try
    {
        MemoryReader reader(m_processHandle);

        // Get player position first
        PlayerState player = GetPlayerState();

        // Scan for monster units (type 3)
        // We need to scan more aggressively for mobs than we did for player
        uintptr_t currentOffset = 0;

        // Get module base for unit table discovery
        MODULEENTRY32 me32 = {sizeof(MODULEENTRY32)};
        HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, m_processId);
        if (hModuleSnap == INVALID_HANDLE_VALUE)
            return mobs;

        uintptr_t moduleBase = 0;
        if (Module32First(hModuleSnap, &me32))
        {
            do
            {
                if (_wcsicmp(me32.szModule, L"D2R.exe") == 0)
                {
                    moduleBase = (uintptr_t)me32.modBaseAddr;
                    break;
                }
            } while (Module32Next(hModuleSnap, &me32));
        }
        CloseHandle(hModuleSnap);

        if (!moduleBase)
            return mobs;

        // Discover unit table
        uintptr_t unitTablePtr = DiscoverUnitTableBase(reader, moduleBase);
        if (!unitTablePtr)
            return mobs;

        // Read unit table pointer
        uintptr_t unitTableBase = reader.Read<uintptr_t>(unitTablePtr);
        if (!unitTableBase)
            return mobs;

        // Scan with larger range for mobs (up to 5000 units)
        currentOffset = unitTableBase;

        for (int i = 0; i < 5000; i++)
        {
            // Alternate stride
            if ((i % 2) == 1)
                currentOffset += 0x48;
            else
                currentOffset += 0x170;

            // Check unit type
            byte unitType = reader.Read<byte>(currentOffset + UnitOffsets::TYPE);

            // Look for monsters (type 3)
            if (unitType == UNIT_TYPE_MONSTER)
            {
                // Read mob data
                float mobX = reader.Read<float>(currentOffset + UnitOffsets::POSITION_X);
                float mobY = reader.Read<float>(currentOffset + UnitOffsets::POSITION_Y);
                int life = reader.Read<int>(currentOffset + UnitOffsets::LIFE);

                // Calculate distance
                float dx = mobX - player.position.x;
                float dy = mobY - player.position.y;
                float distance = sqrt(dx * dx + dy * dy);

                // Check if in range and alive
                if (distance <= radius && life > 0)
                {
                    MobInfo mob;
                    mob.position.x = mobX;
                    mob.position.y = mobY;
                    mob.uniqueId = reader.Read<int>(currentOffset + UnitOffsets::UNIQUE_ID);
                    mob.isAlive = (life > 0);
                    mob.experience = 10; // Placeholder
                    mobs.push_back(mob);

                    if (mobs.size() >= 100) // Safety limit
                        break;
                }
            }

            // Safety check
            if (currentOffset == 0 || currentOffset > 0x00007FFFFFFF000000ULL)
                break;
        }

        if (!mobs.empty())
            return mobs;
    }
    catch (...)
    {
        // Fall through to fallback
    }

    // FALLBACK: Generate mock mobs
    const float mockMobPositions[][2] = {
        {100, 50}, {150, 0}, {100, -50}, {0, -100},
        {-100, -50}, {-150, 0}, {-100, 50}, {0, 100},
    };

    PlayerState player = GetPlayerState();
    for (int i = 0; i < 8; i++)
    {
        Vector2D mockPos;
        mockPos.x = player.position.x + mockMobPositions[i][0];
        mockPos.y = player.position.y + mockMobPositions[i][1];

        float dx = mockPos.x - player.position.x;
        float dy = mockPos.y - player.position.y;
        float distance = sqrt(dx * dx + dy * dy);

        if (distance <= radius && distance > 0)
        {
            MobInfo mob;
            mob.position = mockPos;
            mob.uniqueId = 1000 + i;
            mob.isAlive = true;
            mob.experience = 10;
            mobs.push_back(mob);
        }
    }

    return mobs;
}

