/**
 * Gets the D2R module base address for unit table discovery
 */
uintptr_t BotEngine::GetUnitTableBase(const MemoryReader& reader) const
{
    try
    {
        MODULEENTRY32 me32 = {sizeof(MODULEENTRY32)};
        HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, m_processId);
        if (hModuleSnap == INVALID_HANDLE_VALUE)
            return 0;

        uintptr_t moduleBase = 0;
        if (Module32First(hModuleSnap, &me32))
        {
            do
            {
                if (_wcsicmp(me32.szModule, L"D2R.exe") == 0)
                {
                    moduleBase = (uintptr_t)me32.modBaseAddr;
                    break;
                }
            } while (Module32Next(hModuleSnap, &me32));
        }
        CloseHandle(hModuleSnap);

        return moduleBase;
    }
    catch (...)
    {
        return 0;
    }
}

/**
 * Scans the unit table for a unit of specific type
 * Mimics BMBot's unit scanning with 0x48 and 0x170 byte stride alternation
 */
uintptr_t BotEngine::FindUnitByType(const MemoryReader& reader, int targetType, int maxScans) const
{
    if (!m_processHandle)
        return 0;

    try
    {
        // Get D2R module base
        uintptr_t moduleBase = GetUnitTableBase(reader);
        if (!moduleBase)
            return 0;

        // Discover unit table
        uintptr_t unitTablePtr = DiscoverUnitTableBase(reader, moduleBase);
        if (!unitTablePtr)
            return 0;

        // Read unit table pointer
        uintptr_t unitTableBase = reader.Read<uintptr_t>(unitTablePtr);
        if (!unitTableBase)
            return 0;

        // Scan with alternating stride (like BMBot)
        // 0x48 and 0x170 byte sizes for different unit types
        uintptr_t currentOffset = unitTableBase;

        for (int i = 0; i < maxScans; i++)
        {
            // Alternate stride: 0x48 on odd, 0x170 on even
            if ((i % 2) == 1)
                currentOffset += 0x48;
            else
                currentOffset += 0x170;

            // Check unit type at offset 0x00
            byte unitType = reader.Read<byte>(currentOffset + UnitOffsets::TYPE);

            if (unitType == targetType)
            {
                // Found the unit type we're looking for
                return currentOffset;
            }

            // Safety check for bad pointer
            if (currentOffset == 0 || currentOffset > 0x00007FFFFFFF000000ULL)
                break;
        }
    }
    catch (...)
    {
        // Fall through to fallback
    }

    return 0;
}

